def timeout_result(*, retry_after=None):
    result = {'ok': False, 'reason': 'timeout'}
    if retry_after is None:
        return result
    if isinstance(retry_after, bool) or not isinstance(retry_after, int):
        raise TypeError('retry_after must be a nonnegative int')
    if retry_after < 0:
        raise ValueError('retry_after must be nonnegative')
    result['retry_after'] = retry_after
    return result

